package br.com.brindespro.admin;
import jakarta.persistence.*;import java.time.OffsetDateTime;
@Entity @Table(name="audit_logs") public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id;@Column(name="user_id") public Long userId;@Column(name="entity_type",nullable=false) public String entityType;@Column(name="entity_id",nullable=false) public Long entityId;@Column(nullable=false) public String action;@Column(length=2000) public String details;@Column(name="created_at",nullable=false) public OffsetDateTime createdAt=OffsetDateTime.now();protected AuditLog(){} public AuditLog(Long userId,String entityType,Long entityId,String action,String details){this.userId=userId;this.entityType=entityType;this.entityId=entityId;this.action=action;this.details=details;} }
